#!/bin/sh
# 编译四阶段：-E / -S / -c / 链接 各自的产物
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.h << 'EOF'
int add(int a, int b);
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

gcc -E util.c -o util.i        # ① 预处理：仍是 C 源码（含展开的头文件）
gcc -S util.c -o util.s        # ② 编译：汇编代码
gcc -c util.c -o util.o        # ③ 汇编：可重定位目标文件
wc -l util.c util.i util.s    # 行数变化：预处理会大幅膨胀
head -3 util.s                 # 汇编片段
gcc -c main.c -o main.o        # 编译 main.c 为可重定位目标文件
gcc main.o util.o -o app.exe   # ④ 链接：合并目标文件并补齐 CRT 启动代码
./app
